package com.packetanalyzer.stats; import java.util.concurrent.atomic.*; import java.util.concurrent.*; public final class Statistics {public final LongAdder total=new LongAdder(),bytes=new LongAdder(),forwarded=new LongAdder(),dropped=new LongAdder();public final ConcurrentMap<String,LongAdder> apps=new ConcurrentHashMap<>();public void app(String a){apps.computeIfAbsent(a,k->new LongAdder()).increment();}public String report(){StringBuilder s=new StringBuilder("Packets: ").append(total.sum()).append("\nBytes: ").append(bytes.sum()).append("\nForwarded: ").append(forwarded.sum()).append("\nDropped: ").append(dropped.sum()).append("\nApplications:\n");apps.forEach((k,v)->s.append("  ").append(k).append(": ").append(v.sum()).append('\n'));return s.toString();}}
